// Block (composition) — range context paired with page navigation.
import type { Ref } from "react";
import { Pagination } from "../components/Pagination";
import { Select, SelectItem } from "../components/Select";
import { Stack } from "../layouts/Stack";
import "./PaginationBar.css";

export interface PaginationBarProps {
  /** Current page, starting at one. */
  page: number;
  pageSize: number;
  total: number;
  onPageChange?: (page: number) => void;
  /**
   * Page sizes to offer. When set, a page-size selector (a `filled` Select at the Pagination's own size) joins the bar, as
   * in a dashboard's "50개씩 보기". Leave unset for a fixed page size.
   */
  pageSizeOptions?: number[];
  /** Called with the chosen page size. */
  onPageSizeChange?: (pageSize: number) => void;
  /** Builds each page-size option's text. */
  pageSizeLabel?: (pageSize: number) => string;
  /** Accessible name for the page-size selector, which has no visible label. */
  pageSizeSelectorLabel?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function PaginationBar({
  page,
  pageSize,
  total,
  onPageChange,
  pageSizeOptions,
  onPageSizeChange,
  pageSizeLabel = (size) => `${size} per page`,
  pageSizeSelectorLabel = "Rows per page",
  className,
  ref,
}: PaginationBarProps) {
  const safeTotal = Math.max(total, 0);
  const safePageSize = Math.max(pageSize, 1);
  const totalPages = Math.max(1, Math.ceil(safeTotal / safePageSize));
  const currentPage = Math.min(Math.max(page, 1), totalPages);
  const rangeStart = safeTotal === 0 ? 0 : (currentPage - 1) * safePageSize + 1;
  const rangeEnd = Math.min(currentPage * safePageSize, safeTotal);
  // The current size is always offered, so the selector never shows an empty placeholder when a
  // consumer's page size is not one of its options.
  const sizeOptions = !pageSizeOptions?.length
    ? []
    : pageSizeOptions.includes(safePageSize)
      ? [...new Set(pageSizeOptions)]
      : [...new Set([...pageSizeOptions, safePageSize])].sort((a, b) => a - b);

  return (
    <Stack
      ref={ref}
      direction={{ small: "column", medium: "row" }}
      justify="between"
      align="center"
      gap="small"
      className={className ? `sd-paginationbar ${className}` : "sd-paginationbar"}
    >
      <span className="sd-paginationbar__summary sd-type-caption-medium">
        Showing {rangeStart}–{rangeEnd} of {safeTotal}
      </span>
      {/* spacing: attachment — the summary reads the pager beside it */}
      <Stack direction="row" align="center" gap="small">
        {sizeOptions.length > 0 && (
          <Select
            variant="filled"
            size="medium"
            aria-label={pageSizeSelectorLabel}
            selectedKey={String(safePageSize)}
            onSelectionChange={(key) => {
              if (key != null) onPageSizeChange?.(Number(key));
            }}
          >
            {sizeOptions.map((size) => (
              <SelectItem key={size} id={String(size)}>
                {pageSizeLabel(size)}
              </SelectItem>
            ))}
          </Select>
        )}
        <Pagination
          page={currentPage}
          total={totalPages}
          onPageChange={onPageChange ?? (() => undefined)}
        />
      </Stack>
    </Stack>
  );
}

/* PaginationBar.css — full-width responsive arrangement only. */
.sd-paginationbar {
  width: 100%;
}

.sd-paginationbar__summary {
  flex: none;
}
